package main

import (
	"html/template"
	"log"
	"net/http"
)

// HandleProductSearch handles product search requests and displays results
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	// Get the keyword from URL query parameter
	keyword := r.URL.Query().Get("keyword")
	if keyword == "" {
		keyword = "No keyword provided"
	}

	// Set content type to HTML
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Define the HTML template
	tmpl := template.Must(template.New("search").Parse(`
<!DOCTYPE html>
<html>
<head>
    <title>Search Results: {{.Keyword}}</title>
</head>
<body>
    <h2>Search Results: {{.Keyword}}</h2>
</body>
</html>
`))

	// Execute the template with the keyword data
	err := tmpl.Execute(w, struct{ Keyword string }{Keyword: keyword})
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}
}

func main() {
	// Register the handler for the search endpoint
	http.HandleFunc("/search", HandleProductSearch)

	// Start the server on port 8080
	log.Println("Server starting on http://localhost:8080")
	log.Println("Try: http://localhost:8080/search?keyword=golang")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal("Server failed to start:", err)
	}
}

