import (
    "html"
    "net/http"
    "strings"
)

// HandleProductSearch handles product search results page with analytics support
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
    // Get the keyword from URL query parameter
    keyword := strings.TrimSpace(r.URL.Query().Get("keyword"))

    // Set response content type to HTML
    w.Header().Set("Content-Type", "text/html; charset=utf-8")

    // Build the HTML response
    // Escape the keyword to prevent XSS attacks
    escapedKeyword := html.EscapeString(keyword)

    // If keyword is empty, display a default message
    if escapedKeyword == "" {
        w.WriteHeader(http.StatusOK)
        w.Write([]byte(`<!DOCTYPE html>
<html>
<head>
    <title>Product Search</title>
</head>
<body>
    <h2>Search Results: </h2>
    <p>Please provide a search keyword.</p>
</body>
</html>`))
        return
    }

    // Display search results with the keyword
    w.WriteHeader(http.StatusOK)
    w.Write([]byte(`<!DOCTYPE html>
<html>
<head>
    <title>Search Results: ` + escapedKeyword + `</title>
</head>
<body>
    <h2>Search Results: ` + escapedKeyword + `</h2>
    <p>Showing results for: <strong>` + escapedKeyword + `</strong></p>
    <!-- Analytics tracking placeholder -->
    <script>
        // Analytics tracking code would go here
        console.log('Search tracked: ' + '` + escapedKeyword + `');
    </script>
</body>
</html>`))
}

func main() {
    // Register the handler for the /search endpoint
    http.HandleFunc("/search", HandleProductSearch)

    // Start the HTTP server on port 8080
    http.ListenAndServe(":8080", nil)
}

